INSERT INTO public.exercise_library (id, name, slug, body_area, movement_type, equipment, level, primary_muscles, secondary_muscles, instructions, image_paths, legacy_names) VALUES
  ('Barbell_Guillotine_Bench_Press', 'Barbell Guillotine Bench Press', 'barbell-guillotine-bench-press', 'Chest', 'Push', ARRAY['Barbell']::text[], 'Intermediate', ARRAY['chest']::text[], ARRAY['shoulders', 'triceps']::text[], ARRAY['Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.', 'As you breathe in, bring the bar down slowly until it is about 1 inch from your neck.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], ARRAY['/exercises/barbell-guillotine-bench-press-1.webp', '/exercises/barbell-guillotine-bench-press-2.webp']::text[], ARRAY[]::text[]),
  ('Barbell_Seated_Calf_Raise', 'Barbell Seated Calf Raise', 'barbell-seated-calf-raise', 'Legs & Glutes', 'Push', ARRAY['Barbell']::text[], 'Beginner', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['Place a block about 12 inches in front of a flat bench.', 'Sit on the bench and place the ball of your feet on the block.', 'Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position.', 'Raise up on your toes as high as possible as you squeeze the calves and as you breathe out.', 'After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/barbell-seated-calf-raise-1.webp', '/exercises/barbell-seated-calf-raise-2.webp']::text[], ARRAY[]::text[]),
  ('Barbell_Shoulder_Press', 'Barbell Shoulder Press', 'barbell-shoulder-press', 'Shoulders', 'Push', ARRAY['Barbell']::text[], 'Intermediate', ARRAY['shoulders']::text[], ARRAY['chest', 'triceps']::text[], ARRAY['Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).', 'Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the shoulders slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/barbell-shoulder-press-1.webp', '/exercises/barbell-shoulder-press-2.webp']::text[], ARRAY[]::text[]),
  ('Barbell_Shrug', 'Barbell Shrug', 'barbell-shrug', 'Back', 'Pull', ARRAY['Barbell']::text[], 'Beginner', ARRAY['traps']::text[], ARRAY[]::text[], ARRAY['Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.', 'Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/barbell-shrug-1.webp', '/exercises/barbell-shrug-2.webp']::text[], ARRAY[]::text[]),
  ('Barbell_Side_Bend', 'Barbell Side Bend', 'barbell-side-bend', 'Core', 'Core', ARRAY['Barbell']::text[], 'Beginner', ARRAY['abdominals']::text[], ARRAY['lower back']::text[], ARRAY['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.', 'While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.', 'Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/barbell-side-bend-1.webp', '/exercises/barbell-side-bend-2.webp']::text[], ARRAY[]::text[]),
  ('Barbell_Squat_To_A_Bench', 'Barbell Squat To A Bench', 'barbell-squat-to-a-bench', 'Legs & Glutes', 'Squat', ARRAY['Barbell']::text[], 'Expert', ARRAY['quadriceps']::text[], ARRAY['calves', 'glutes', 'hamstrings', 'lower back']::text[], ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth.', '', 'Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees and sitting your hips back as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs and extend the hips to go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/barbell-squat-to-a-bench-1.webp', '/exercises/barbell-squat-to-a-bench-2.webp']::text[], ARRAY[]::text[]),
  ('Bench_Dips', 'Bench Dips', 'bench-dips', 'Arms', 'Push', ARRAY['Bodyweight']::text[], 'Beginner', ARRAY['triceps']::text[], ARRAY['chest', 'shoulders']::text[], ARRAY['For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.', 'Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.', 'Using your triceps to bring your torso up again, lift yourself back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/bench-dips-1.webp', '/exercises/bench-dips-2.webp']::text[], ARRAY[]::text[]),
  ('Bench_Jump', 'Bench Jump', 'bench-jump', 'Legs & Glutes', 'Push', ARRAY['Bodyweight']::text[], 'Intermediate', ARRAY['quadriceps']::text[], ARRAY['calves', 'glutes', 'hamstrings']::text[], ARRAY['Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position.', 'Perform a short squat in preparation for the jump; swing your arms behind you.', 'Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.', 'Jump over the bench, landing with the knees bent, absorbing the impact through the legs.', 'Turn around and face the opposite direction, then jump back over the bench.']::text[], ARRAY['/exercises/bench-jump-1.webp', '/exercises/bench-jump-2.webp']::text[], ARRAY[]::text[]),
  ('Bench_Press_-_Powerlifting', 'Bench Press - Powerlifting', 'bench-press-powerlifting', 'Arms', 'Push', ARRAY['Barbell']::text[], 'Intermediate', ARRAY['triceps']::text[], ARRAY['chest', 'forearms', 'lats', 'shoulders']::text[], ARRAY['Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.', 'However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.', 'Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.', 'Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[], ARRAY['/exercises/bench-press-powerlifting-1.webp', '/exercises/bench-press-powerlifting-2.webp']::text[], ARRAY[]::text[]),
  ('Bench_Press_-_With_Bands', 'Bench Press - With Bands', 'bench-press-with-bands', 'Chest', 'Push', ARRAY['Band']::text[], 'Beginner', ARRAY['chest']::text[], ARRAY['shoulders', 'triceps']::text[], ARRAY['Using a flat bench secure a band under the leg of the bench that is nearest to your head.', 'Once the band is secure, grab it by both handles and lie down on the bench.', 'Extend your arms so that you are holding the band handles in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.', 'As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[], ARRAY['/exercises/bench-press-with-bands-1.webp', '/exercises/bench-press-with-bands-2.webp']::text[], ARRAY[]::text[]),
  ('Bench_Press_with_Chains', 'Bench Press with Chains', 'bench-press-with-chains', 'Arms', 'Push', ARRAY['Barbell']::text[], 'Expert', ARRAY['triceps']::text[], ARRAY['chest', 'lats', 'shoulders']::text[], ARRAY['Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar.', 'Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.', 'Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.', 'Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[], ARRAY['/exercises/bench-press-with-chains-1.webp', '/exercises/bench-press-with-chains-2.webp']::text[], ARRAY[]::text[]),
  ('Bent_Over_Two-Dumbbell_Row', 'Bent Over Two-Dumbbell Row', 'bent-over-two-dumbbell-row', 'Back', 'Pull', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['middle back']::text[], ARRAY['biceps', 'lats', 'shoulders']::text[], ARRAY['With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/bent-over-two-dumbbell-row-1.webp', '/exercises/bent-over-two-dumbbell-row-2.webp']::text[], ARRAY[]::text[]),
  ('Bent_Press', 'Bent Press', 'bent-press', 'Core', 'Core', ARRAY['Kettlebell']::text[], 'Expert', ARRAY['abdominals']::text[], ARRAY['glutes', 'hamstrings', 'lower back', 'quadriceps', 'shoulders', 'triceps']::text[], ARRAY['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.', 'Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.', 'Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions.']::text[], ARRAY['/exercises/bent-press-1.webp', '/exercises/bent-press-2.webp']::text[], ARRAY[]::text[]),
  ('Bicycling_Stationary', 'Bicycling, Stationary', 'bicycling-stationary', 'Cardio', 'Cardio', ARRAY['Machine']::text[], 'Beginner', ARRAY['quadriceps']::text[], ARRAY['calves', 'glutes', 'hamstrings']::text[], ARRAY['To begin, seat yourself on the bike and adjust the seat to your height.', 'Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.']::text[], ARRAY['/exercises/bicycling-stationary-1.webp', '/exercises/bicycling-stationary-2.webp']::text[], ARRAY[]::text[]),
  ('Body-Up', 'Body-Up', 'body-up', 'Arms', 'Push', ARRAY['Bodyweight']::text[], 'Intermediate', ARRAY['triceps']::text[], ARRAY['abdominals', 'forearms']::text[], ARRAY['Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.', 'Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.', 'Slowly lower your forearms back to the ground by allowing the elbows to flex.', 'Repeat.']::text[], ARRAY['/exercises/body-up-1.webp', '/exercises/body-up-2.webp']::text[], ARRAY[]::text[]),
  ('Bosu_Ball_Cable_Crunch_With_Side_Bends', 'Bosu Ball Cable Crunch With Side Bends', 'bosu-ball-cable-crunch-with-side-bends', 'Core', 'Core', ARRAY['Machine']::text[], 'Beginner', ARRAY['abdominals']::text[], ARRAY[]::text[], ARRAY['Connect a standard handle to each arm of a cable machine, and position them in the most downward position.', 'Grab a Bosu Ball and position it in front and center of the cable machine.', 'Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.', 'With both hands, reach back and grab the handle of each cable.', 'With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.', 'Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms.', 'Maintain the rigid position with your arms. Slowly descend back to the starting position with your back arched around the Bosu Ball and your abdominals elongated.', 'Repeat the same series of movements to failure.', 'Once you reach failure, keep your abs tight and raise your torso into plank position so your back is elevated off the Bosu Ball.', 'Lower your arms down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques.']::text[], ARRAY['/exercises/bosu-ball-cable-crunch-with-side-bends-1.webp', '/exercises/bosu-ball-cable-crunch-with-side-bends-2.webp']::text[], ARRAY[]::text[]),
  ('Bottoms-Up_Clean_From_The_Hang_Position', 'Bottoms-Up Clean From The Hang Position', 'bottoms-up-clean-from-the-hang-position', 'Arms', 'Pull', ARRAY['Kettlebell']::text[], 'Intermediate', ARRAY['forearms']::text[], ARRAY['biceps', 'shoulders']::text[], ARRAY['Initiate the exercise by standing upright with a kettlebell in one hand.', 'Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder.']::text[], ARRAY['/exercises/bottoms-up-clean-from-the-hang-position-1.webp', '/exercises/bottoms-up-clean-from-the-hang-position-2.webp']::text[], ARRAY[]::text[]),
  ('Butterfly', 'Butterfly', 'butterfly', 'Chest', 'Pull', ARRAY['Machine']::text[], 'Beginner', ARRAY['chest']::text[], ARRAY[]::text[], ARRAY['Sit on the machine with your back flat on the pad.', 'Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.', 'Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.', 'Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/butterfly-1.webp', '/exercises/butterfly-2.webp']::text[], ARRAY[]::text[]),
  ('Cable_Deadlifts', 'Cable Deadlifts', 'cable-deadlifts', 'Legs & Glutes', 'Hinge', ARRAY['Machine']::text[], 'Beginner', ARRAY['quadriceps']::text[], ARRAY['forearms', 'glutes', 'hamstrings', 'lower back']::text[], ARRAY['Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights.', 'To begin, squat down be flexing your hips and knees until you can reach the handles.', 'After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement.', 'After reaching a full standing position, Return to the starting position and repeat.']::text[], ARRAY['/exercises/cable-deadlifts-1.webp', '/exercises/cable-deadlifts-2.webp']::text[], ARRAY[]::text[]),
  ('Cable_Hammer_Curls_-_Rope_Attachment', 'Cable Hammer Curls - Rope Attachment', 'cable-hammer-curls-rope-attachment', 'Arms', 'Pull', ARRAY['Machine']::text[], 'Beginner', ARRAY['biceps']::text[], ARRAY[]::text[], ARRAY['Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.', 'Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.', 'Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.', 'Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.', 'After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/cable-hammer-curls-rope-attachment-1.webp', '/exercises/cable-hammer-curls-rope-attachment-2.webp']::text[], ARRAY[]::text[]),
  ('Cable_Incline_Pushdown', 'Cable Incline Pushdown', 'cable-incline-pushdown', 'Back', 'Pull', ARRAY['Machine']::text[], 'Beginner', ARRAY['lats']::text[], ARRAY[]::text[], ARRAY['Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.', 'Grasp the straight bar attachment overhead with a pronated (overhand; palms down) shoulder width grip and extend your arms in front of you. The bar should be around 2 inches away from your upper thighs. This will be your starting position.', 'Keeping the upper arms stationary, lift your arms back in a semi circle until the bar is straight over your head. Breathe in during this portion of the movement.', 'Slowly go back to the starting position using your lats and hold the contraction once you reach the starting position. Breathe out during the execution of this movement.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/cable-incline-pushdown-1.webp', '/exercises/cable-incline-pushdown-2.webp']::text[], ARRAY[]::text[]),
  ('Calf_Raise_On_A_Dumbbell', 'Calf Raise On A Dumbbell', 'calf-raise-on-a-dumbbell', 'Legs & Glutes', 'Push', ARRAY['Dumbbell']::text[], 'Intermediate', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise.', 'Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position.', 'Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement. Contract the calf hard at the top and hold for a second. Tip: As you come up, roll the dumbbell slightly backward.', 'Now inhale as you roll the dumbbell slightly forward as you come down to get a better stretch.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/calf-raise-on-a-dumbbell-1.webp', '/exercises/calf-raise-on-a-dumbbell-2.webp']::text[], ARRAY[]::text[]),
  ('Clean', 'Clean', 'clean', 'Full Body', 'Pull', ARRAY['Barbell']::text[], 'Intermediate', ARRAY['hamstrings']::text[], ARRAY['calves', 'forearms', 'glutes', 'lower back', 'quadriceps', 'shoulders', 'traps']::text[], ARRAY['With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', '', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[], ARRAY['/exercises/clean-1.webp', '/exercises/clean-2.webp']::text[], ARRAY[]::text[]),
  ('Clean_Deadlift', 'Clean Deadlift', 'clean-deadlift', 'Full Body', 'Hinge', ARRAY['Barbell']::text[], 'Beginner', ARRAY['hamstrings']::text[], ARRAY['forearms', 'glutes', 'lower back', 'middle back', 'quadriceps', 'traps']::text[], ARRAY['Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.', 'Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar''s path.', 'After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended.']::text[], ARRAY['/exercises/clean-deadlift-1.webp', '/exercises/clean-deadlift-2.webp']::text[], ARRAY[]::text[]),
  ('Clean_and_Jerk', 'Clean and Jerk', 'clean-and-jerk', 'Full Body', 'Push', ARRAY['Barbell']::text[], 'Expert', ARRAY['shoulders']::text[], ARRAY['abdominals', 'glutes', 'hamstrings', 'lower back', 'quadriceps', 'traps', 'triceps']::text[], ARRAY['With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.', 'The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.', 'Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.', 'At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position.']::text[], ARRAY['/exercises/clean-and-jerk-1.webp', '/exercises/clean-and-jerk-2.webp']::text[], ARRAY[]::text[]),
  ('Clock_Push-Up', 'Clock Push-Up', 'clock-push-up', 'Chest', 'Push', ARRAY['Bodyweight']::text[], 'Intermediate', ARRAY['chest']::text[], ARRAY['shoulders', 'triceps']::text[], ARRAY['Move into a prone position on the floor, supporting your weight on your hands and toes.', 'Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.', 'Descend by flexing at the elbow, lowering your chest toward the ground.', 'At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to "jump" 12-18 inches to one side.', 'As you accelerate up, move your outside foot away from your direction of travel. Leaving the ground, shift your body about 30 degrees for the next repetition.', 'Return to the starting position and repeat the exercise, working all the way around until you are back where you started.']::text[], ARRAY['/exercises/clock-push-up-1.webp', '/exercises/clock-push-up-2.webp']::text[], ARRAY[]::text[]),
  ('Deadlift_with_Bands', 'Deadlift with Bands', 'deadlift-with-bands', 'Back', 'Hinge', ARRAY['Barbell']::text[], 'Expert', ARRAY['lower back']::text[], ARRAY['forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps']::text[], ARRAY['To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack.', 'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[], ARRAY['/exercises/deadlift-with-bands-1.webp', '/exercises/deadlift-with-bands-2.webp']::text[], ARRAY[]::text[]),
  ('Decline_Crunch', 'Decline Crunch', 'decline-crunch', 'Core', 'Core', ARRAY['Bodyweight']::text[], 'Intermediate', ARRAY['abdominals']::text[], ARRAY[]::text[], ARRAY['Secure your legs at the end of the decline bench and lie down.', 'Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.', 'While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.', 'Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.', 'After the one second contraction, begin to come down slowly again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], ARRAY['/exercises/decline-crunch-1.webp', '/exercises/decline-crunch-2.webp']::text[], ARRAY[]::text[]),
  ('Decline_Dumbbell_Bench_Press', 'Decline Dumbbell Bench Press', 'decline-dumbbell-bench-press', 'Chest', 'Push', ARRAY['Dumbbell']::text[], 'Beginner', ARRAY['chest']::text[], ARRAY['shoulders', 'triceps']::text[], ARRAY['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times. Tip: Throughout the motion, the forearms should always be perpendicular to the floor.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up..', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[], ARRAY['/exercises/decline-dumbbell-bench-press-1.webp', '/exercises/decline-dumbbell-bench-press-2.webp']::text[], ARRAY[]::text[]),
  ('Double_Kettlebell_Snatch', 'Double Kettlebell Snatch', 'double-kettlebell-snatch', 'Shoulders', 'Pull', ARRAY['Kettlebell']::text[], 'Expert', ARRAY['shoulders']::text[], ARRAY['glutes', 'hamstrings', 'quadriceps']::text[], ARRAY['Place two kettlebells behind your feet. Bend your knees and sit back to pick up the kettlebells.', 'Swing the kettlebells between your legs forcefully and reverse the direction.', 'Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.']::text[], ARRAY['/exercises/double-kettlebell-snatch-1.webp', '/exercises/double-kettlebell-snatch-2.webp']::text[], ARRAY[]::text[])
